CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 NUMERIC COLLATE NOCASE, c1 REAL, c2 TEXT CHECK(c2 IS NULL OR length(c2) < 40), c3 NUMERIC);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(1.0e15, -2, -559, 'sigma');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(123456789012, x'1e', 'omicron', -5);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES('42', '1e3', -229.24, NULL);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 NUMERIC COLLATE NOCASE, c1 VARCHAR(10) DEFAULT 'd', c2 NUMERIC DEFAULT 'd', c3 TEXT, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES('chi', -1, -589, -302, 3);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(708, -436.723, x'66ccedfaa2', NULL, 7);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(-313.3, NULL, 254, x'07616ece', NULL);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 REAL CHECK(c0 IS NULL OR length(c0) < 40), c1 BLOB CHECK(c1 IS NULL OR length(c1) < 40), c2 VARCHAR(10) COLLATE NOCASE, ref INTEGER REFERENCES t1(id));
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', 2, 0), instr('a%b', 'pi'), replace('a%b', 'e', ''), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '_', 'a%b' GLOB '?', char(90, 444), 'a%b' || 'pi', 'a%b' < 'pi', 'a%b' = 'pi' COLLATE NOCASE;
SELECT length('Lambda'), upper('Lambda'), lower('Lambda'), substr('Lambda', 4, 3), instr('Lambda', 'kappa'), replace('Lambda', '', 'XY'), trim('Lambda'), ltrim('Lambda', 'ab'), hex('Lambda'), quote('Lambda'), unicode('Lambda'), 'Lambda' LIKE '%a_', 'Lambda' GLOB '*[a-m]*', char(77, 845), 'Lambda' || 'kappa', 'Lambda' < 'kappa', 'Lambda' = 'kappa' COLLATE NOCASE;
SELECT length('delta'), upper('delta'), lower('delta'), substr('delta', 0, 2), instr('delta', 'Lambda'), replace('delta', 'a', ''), trim('delta'), ltrim('delta', 'ab'), hex('delta'), quote('delta'), unicode('delta'), 'delta' LIKE '%a_', 'delta' GLOB '*[a-m]*', char(83, 979), 'delta' || 'Lambda', 'delta' < 'Lambda', 'delta' = 'Lambda' COLLATE NOCASE;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', 0, 5), instr('x_y', ' pad '), replace('x_y', 'a', '_'), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE '_', 'x_y' GLOB '*[a-m]*', char(85, 457), 'x_y' || ' pad ', 'x_y' < ' pad ', 'x_y' = ' pad ' COLLATE NOCASE;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', -3, 4), instr('x_y', '-7'), replace('x_y', 'a', '_'), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE '_', 'x_y' GLOB '?', char(82, 709), 'x_y' || '-7', 'x_y' < '-7', 'x_y' = '-7' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 0, 0), instr('sigma', 'upsilon'), replace('sigma', 'a', 'XY'), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '%a_', 'sigma' GLOB '*[a-m]*', char(69, 593), 'sigma' || 'upsilon', 'sigma' < 'upsilon', 'sigma' = 'upsilon' COLLATE NOCASE;
SELECT length('MU'), upper('MU'), lower('MU'), substr('MU', 3, 0), instr('MU', 'omega'), replace('MU', 'a', 'XY'), trim('MU'), ltrim('MU', 'ab'), hex('MU'), quote('MU'), unicode('MU'), 'MU' LIKE '%é%', 'MU' GLOB '*[a-m]*', char(75, 273), 'MU' || 'omega', 'MU' < 'omega', 'MU' = 'omega' COLLATE NOCASE;
SELECT id, nullif(nullif(iif(x'bb', c1, 592), CAST(c3 AS REAL)), NOT ref BETWEEN nullif(3.141592653589793, -3) AND c1), c2 BETWEEN 464.20 AND -263 FROM t1 ORDER BY id DESC, c0 DESC, c1, c2, c3 DESC, ref;
SELECT 2, -(NULL IS NULL);
SELECT id, (SELECT count(*) FROM t1 WHERE t1.id <= t0.id) FROM t0 ORDER BY c0 DESC, id DESC;
SELECT id FROM t0 WHERE id NOT IN (SELECT id FROM t1 WHERE iif((c3 AND c1), (-470 - 0), NULL)) ORDER BY id;
SELECT id FROM t0 x WHERE EXISTS (SELECT 1 FROM t1 y WHERE y.id = x.id + 2) ORDER BY id;
SELECT c3 FROM t0 EXCEPT SELECT c2 FROM t1 ORDER BY 1 LIMIT 3 OFFSET 2;
